import math, random, json, numpy as np
from sigma_ground.field.interface.nbody import CelestialBody, NBodySystem
G=6.6743e-11  # Mentat lookup_constant
N,M,b=128,1e12,5000.0
def plummer(seed):
    rng=random.Random(seed); m=M/N; P=[]; V=[]
    for _ in range(N):
        r=b/math.sqrt(rng.random()**(-2/3)-1); ct=2*rng.random()-1; st=math.sqrt(1-ct*ct); ph=2*math.pi*rng.random(); P.append([r*st*math.cos(ph),r*st*math.sin(ph),r*ct])
        ve=math.sqrt(2*G*M)*(r*r+b*b)**-0.25
        while True:
            q,g=rng.random(),0.1*rng.random()
            if g<q*q*(1-q*q)**3.5: break
        v=q*ve; ct=2*rng.random()-1; st=math.sqrt(1-ct*ct); ph=2*math.pi*rng.random(); V.append([v*st*math.cos(ph),v*st*math.sin(ph),v*ct])
    P,V=np.array(P),np.array(V); P-=P.mean(0); V-=V.mean(0)
    return [CelestialBody(m,P[i],V[i],1.0,0.0) for i in range(N)]
K=lambda s: sum(x.kinetic_energy() for x in s.bodies)
tc=math.sqrt(b**3/(G*M)); dt=tc/300; tr=0.1*N/math.log(N)*tc
for seed in (1,2,3):
    s=NBodySystem(plummer(seed),softening_m=0.02*b)
    for _ in range(int(10*tc/dt)): s.step(dt)
    base=list(s.bodies); K0=K(s); res={}
    for d in (-0.1,-0.05,0.0,0.05,0.1):
        sb=NBodySystem([x.replace(velocity_m_s=x.velocity_m_s*(1+d)) for x in base],softening_m=0.02*b); Ks=[]
        for k in range(int(3*tr/dt)):
            sb.step(dt)
            if k*dt>2*tr: Ks.append(K(sb))
        res[d]=(((1+d)**2-1)*K0, float(np.mean(Ks)))
    xs=[res[d][0] for d in (-0.1,-0.05,0.05,0.1)]; ys=[res[d][1]-res[0.0][1] for d in (-0.1,-0.05,0.05,0.1)]
    print(json.dumps(dict(seed=seed, slope=float(np.polyfit(xs,ys,1)[0]))))

import sys, math, json, numpy as np; sys.path.insert(0,'tools'); from mentat_client import mentat
from sigma_ground.inventory.core.sigma import XI
G,_=mentat('lookup_constant',{'name':'G'}); c,_=mentat('lookup_constant',{'name':'c'})
a=5e3; R=math.pi*a; K=2*math.pi*G*a*a; wc=1e-3; rhoc=wc*c*c/(6*math.pi*G*a*a)
r=np.linspace(0,40*R,8001); dr=r[1]; dt=dr/c; x=np.maximum(r/a,1e-9); sh=np.where(r<R,np.sin(x)/x,0.); rho0=rhoc*sh; P0=K*rho0**2
def src(t,mode,eps,om):
    if mode=='mass':
        lam=1+eps*math.sin(om*t); xx=np.maximum(r/(a*lam),1e-9); rho=rhoc*np.where(r<R*lam,np.sin(xx)/xx,0.)/lam**3; P=P0
    else: rho=rho0; P=P0*(1+eps*math.sin(om*t))
    return (8*math.pi*G*XI/c**4)*(rho*c*c-3*P)
def run(mode,om,eps=0.05,per=6,probe=int(30*R/dr)):
    v=np.zeros_like(r); vo=v.copy(); t=0.; T=2*math.pi/om; far=[]; first=None
    while t<per*T:
        s=src(t,mode,eps,om); vn=np.empty_like(v)
        vn[1:-1]=2*v[1:-1]-vo[1:-1]+(v[2:]-2*v[1:-1]+v[:-2])+dt*dt*c*c*r[1:-1]*s[1:-1]; vn[0]=0.; vn[-1]=v[-2]
        vo,v,t=v,vn,t+dt
        if first is None and abs(v[probe])>1e-30: first=t
        if t>(per-3)*T: far.append(v[probe])
    return dict(amp=float(np.std(far)*math.sqrt(2)), arrival_over_rmR_c=first/((r[probe]-R)/c))
for om in (2e2,4e2,8e2,1.6e3): print(om, run('mass',om), run('pressure',om))

